impl IntoElementOrDocument for ElementOrDocument<'_> {}

impl<'a> ElementOrDocument<'a> {
    /// The member a parameter was given, as its enum, to `match`: the value itself.
    #[cfg_attr(rust_js, rust_js::link_name = "this")]
    #[allow(unused_variables)]
    pub fn of(this: impl IntoElementOrDocument + 'a) -> ElementOrDocument<'a> {
        unreachable!()
    }
}

/// `Element | Text`: each variant's value is the member itself (ADR 0215).
#[cfg_attr(rust_js, rust_js::untagged)]
pub enum ElementOrText<'a> {
    Element(&'a Element),
    Text(&'a Text),
}

impl<'a> From<&'a Element> for ElementOrText<'a> {
    fn from(value: &'a Element) -> Self {
        ElementOrText::Element(value)
    }
}

